import fs from 'node:fs';
import path from 'node:path';
import http from 'node:http';
import {WebSocketServer} from 'ws';
import {OneBot} from '../../src/transport-onebot.js';
import {Memory} from '../../src/memory.js';
import {Brain} from '../../src/brain.js';
import {Role} from '../../src/role.js';
import {createMainDurableTransport,startMainDurableChat} from '../../src/chat-main-durable.js';
const dir=process.argv[2]; let ws,runtime,bot; const pending=[];
const server=http.createServer((req,res)=>{let data='';req.on('data',x=>data+=x);req.on('end',()=>{pending.push(res);process.send({type:'send',message:JSON.parse(data).message});});});
const wss=new WebSocketServer({server});wss.on('connection',s=>{ws=s;process.send({type:'connected'});});
await new Promise(r=>server.listen(0,'127.0.0.1',r));
const port=server.address().port;
let releaseModel; globalThis.fetch=async(url,opts)=>{if(String(url).startsWith('https://model.invalid/')){process.send({type:'model',payload:JSON.parse(opts.body)});if(process.env.HOLD_MODEL==='1') await new Promise(r=>releaseModel=r);return {ok:true,json:async()=>({choices:[{finish_reason:'stop',message:{content:'一\n\n二\n\n三'}}]})};}throw Error('network forbidden');};
const scope={tenant:'companion',platform:'qq',type:'private',session:'private:123',user:'123'};
const mc={enabled:true,trustedProcess:true,trustedScope:scope,authorizedSources:['qq-private-message'],directory:path.join(dir,'store'),backend:'sqlite-fts'};
const brain=new Brain({apiKey:'synthetic',baseUrl:'https://model.invalid/',model:'fixture',role:new Role({cardPath:path.join(dir,'role')}),ownerIds:['123'],memory:new Memory({dir:path.join(dir,'memory')})});
const config={enabled:true,trustLocalCard:true,ownerId:'123',directory:path.join(dir,'journal'),keyPath:path.join(dir,'key'),transport:{trustLoopbackOneBot:true,senderUrl:`http://127.0.0.1:${port}/`}};
const transport=createMainDurableTransport({config,onebot:{wsUrl:`ws://127.0.0.1:${port}`},ownerIds:['123']});
bot=new OneBot({wsUrl:`ws://127.0.0.1:${port}`,httpUrl:'',ingressAuthentication:transport.ingressAuthentication,dataDir:dir,onMessage:m=>runtime.accept(m)});
runtime=startMainDurableChat({config,brain,bot,sender:transport.sender,ownerIds:['123'],memoryConfig:mc});
process.on('message',async m=>{if(m==='release-model') releaseModel?.();if(m==='input') ws.send(JSON.stringify({post_type:'message',message_type:'private',self_id:789,user_id:123,message_id:456,message:[{type:'text',data:{text:'synthetic input'}}]}));if(m==='ack'){const res=pending.shift();res.writeHead(200,{'content-type':'application/json'});res.end(JSON.stringify({status:'ok',retcode:0,data:{message_id:1}}));}if(m==='stop'){runtime.stop();await runtime.close();bot.close();wss.clients.forEach(s=>s.terminate());await new Promise(r=>wss.close(r));await new Promise(r=>server.close(r));process.exit(0);}});
